  <div class="postgen-settings">
    <div class="inline-drawer">
      <div class="inline-drawer-toggle inline-drawer-header">
        <b>正文后续生成</b>
        <div class="inline-drawer-icon fa-solid fa-circle-chevron-down down"></div>
      </div>
      <div class="inline-drawer-content">
        <div class="postgen-block flex-container">
          <input id="postgen-enable" v-model="settings.enabled" type="checkbox" />
          <label for="postgen-enable">启用正文后续生成</label>
        </div>

        <div class="postgen-block">
          <b>API 配置（所有任务共用）</b>
          <div class="flex-container">
            <input v-model="settings.api.apiurl" type="text" placeholder="留空=使用酒馆当前连接" class="text_pole" />
          </div>
          <div class="flex-container">
            <input v-model="settings.api.apiKey" :type="apiKeyVisible ? 'text' : 'password'" placeholder="API Key（可选）" class="text_pole" />
            <input type="button" class="menu_button" :value="apiKeyVisible ? '隐藏' : '显示'" @click="apiKeyVisible = !apiKeyVisible" />
          </div>
          <div class="flex-container">
            <input v-model="settings.api.model" type="text" placeholder="模型（留空=默认模型）" class="text_pole" />
            <input type="button" class="menu_button" :value="fetching ? '拉取中…' : '拉取'" :disabled="fetching" @click="fetchModels" />
          </div>
          <select v-if="fetchedModels.length" v-model="settings.api.model" class="postgen-model-select">
            <option value="">— 选择模型 —</option>
            <option v-for="model in fetchedModels" :key="model" :value="model">{{ model }}</option>
          </select>
          <div class="flex-container">
            <select v-model="settings.api.source" class="postgen-select">
              <option value="auto">自动识别（推荐）</option>
              <option value="openai">OpenAI Chat Completions</option>
              <option value="claude">Anthropic Messages</option>
            </select>
            <input type="button" class="menu_button" :value="testing ? '测试中…' : '测试API'" :disabled="testing" @click="testApi" />
          </div>
          <small class="postgen-hint">{{ apiHint }}</small>
          <small v-if="apiTestStatus" class="postgen-hint" :class="apiTestOk ? 'postgen-ok' : 'postgen-warn'">{{ apiTestStatus }}</small>
        </div>

        <div class="postgen-block">
          <b>生成配置</b>
          <div class="flex-container">
            <input v-model.number="settings.context.ai_messages" type="number" min="0" max="20" class="postgen-num" />
            <label class="postgen-label">前情提要 AI 消息层数</label>
          </div>
          <div class="flex-container">
            <input v-model.number="settings.timeout_seconds" type="number" min="5" max="300" class="postgen-num" />
            <label class="postgen-label">超时秒数</label>
          </div>
          <div class="flex-container">
            <input id="postgen-strip" v-model="settings.strip_regex" type="checkbox" />
            <label for="postgen-strip">发送给主 LLM 前剥离任务标签（自动注册酒馆正则）</label>
          </div>
        </div>

        <div class="postgen-block">
          <div class="flex-container" style="justify-content: space-between">
            <b>任务列表（正文后续的抽象实现）</b>
            <div>
              <input type="button" class="menu_button" value="＋ 添加任务" @click="addTask" />
              <input type="button" class="menu_button" value="恢复默认" @click="resetTasks" />
            </div>
          </div>
          <div v-for="(task, index) in settings.tasks" :key="task.id" class="postgen-task">
            <div class="flex-container">
              <input :id="'postgen-task-enable-' + task.id" v-model="task.enabled" type="checkbox" />
              <label :for="'postgen-task-enable-' + task.id">启用</label>
              <input v-model="task.name" type="text" class="text_pole" placeholder="任务名" style="flex: 1" />
              <input v-model="task.tag" type="text" class="text_pole" placeholder="标签" style="width: 90px" />
            </div>
            <div class="flex-container">
              <input v-model="task.sep" type="text" class="postgen-num" placeholder="分隔符" style="width: 90px" />
